// Text handling and the commented TOML writer reproduce Python (textwrap, str.splitlines) and
// MDATK's tomlio byte for byte (expected results generated by tests/parity/textwrap_cases.py
// and with MDATK's tomlio; see data/README.md).

#include <cmath>
#include <filesystem>
#include <fstream>
#include <limits>
#include <sstream>

#include <gtest/gtest.h>

#include "mdbridge/core/project_file.hpp"
#include "mdbridge/core/text.hpp"
#include "mdbridge/core/toml_writer.hpp"

namespace fs = std::filesystem;
using namespace mdbridge::core;

namespace {

const fs::path kText = fs::path(MDBRIDGE_TEST_DATA) / "text";

std::string readFile(const fs::path& path) {
    std::ifstream in(path, std::ios::binary);
    std::ostringstream text;
    text << in.rdbuf();
    return text.str();
}

std::vector<std::string> strings(const Value* array) {
    std::vector<std::string> out;
    for (const Value& v : *array->get<Array>()) {
        out.push_back(v.stringOr());
    }
    return out;
}

}  // namespace

TEST(PythonText, TextwrapMatchesPython) {
    const Value cases = parseToml(readFile(kText / "textwrap_cases.toml"), "textwrap_cases.toml");
    std::size_t checked = 0;
    for (const Value& c : *cases.find("wrap")->get<Array>()) {
        const std::string text = c.find("text")->stringOr();
        const auto width = static_cast<int>(*c.find("width")->get<std::int64_t>());
        EXPECT_EQ(pythonTextwrap(text, width), strings(c.find("lines"))) << "width " << width << ": " << text;
        ++checked;
    }
    EXPECT_GT(checked, 900u);
}

TEST(PythonText, SplitlinesMatchesPython) {
    const Value cases = parseToml(readFile(kText / "textwrap_cases.toml"), "textwrap_cases.toml");
    for (const Value& c : *cases.find("splitlines")->get<Array>()) {
        const std::string text = c.find("text")->stringOr();
        EXPECT_EQ(pythonSplitlines(text), strings(c.find("lines"))) << text;
    }
}

TEST(PythonText, CountsCharactersAndReplacesInvalidBytes) {
    EXPECT_EQ(characterCount("Mg²⁺ Å 🧬"), 8u);
    EXPECT_EQ(encodeUtf8(decodeUtf8("caf\xe9.pdb")), "caf\xef\xbf\xbd.pdb");  // like MDATK's U+FFFD for undecodable bytes
    EXPECT_EQ(decodeUtf8("\xe2\x82" "A").size(), 3u);  // one replacement per invalid byte
    EXPECT_EQ(pythonStrip("\xc2\xa0 x \t"), "x");
    EXPECT_EQ(pythonRstrip("# "), "#");
}

TEST(TomlWriter, MatchesMdatkTomlio) {
    // the data and comments of the golden file (made with MDATK's tomlio.dumps)
    const Value data = Table{
        {"s", "a \"b\" \\ c\ttab \x01 end"},
        {"m", "line 1\nline \"2\"\r\n\ttabbed \x7f"},
        {"f", 1e-7},
        {"f2", 100000.0},
        {"f3", -0.0},
        {"nan", std::numeric_limits<double>::quiet_NaN()},
        {"inf", -std::numeric_limits<double>::infinity()},
        {"i", -3},
        {"b", true},
        {"none", Value()},
        {"when", DateTime{DateTime::Kind::LocalDateTime, 2026, 10, 15, 14, 32, 5}},
        {"l", Array{1, 2.5, "x", Value(), true}},
        {"long", [] {
             Array a;
             for (int i = 0; i < 40; ++i) {
                 a.emplace_back(i);
             }
             return a;
         }()},
        {"inline", Table{{"a", 1}, {"b None", Value()}, {"c", Array{1, 2}}}},
        {"allnone", Table{{"x", Value()}}},
        {"empty_t", Table{}},
        {"empty_l", Array{}},
        {"weird key", 1},
        {"t", Table{{"k", Value()},
                    {"deep", Table{{"z", "é Å"}}},
                    {"v", Array{Table{{"a", 1}}, Table{{"a", 2}, {"sub", Table{{"q", "r"}}}}}}}},
        {"arr", Array{Table{{"name", "Aptamer"}, {"residues", "1-12"}}, Table{{"name", "Target"}}}},
    };
    const auto doc = [](const std::vector<std::string>& path,
                        const std::vector<const Value*>& stack) -> std::optional<std::string> {
        using P = std::vector<std::string>;
        if (path == P{"s"}) {
            return "A string with a long comment that has to be wrapped because it is longer than the width of a line "
                   "in the project file, with self-contained hyphenation.";
        }
        if (path == P{"none"}) {
            return "Not set: written as a comment.";
        }
        if (path == P{"t"}) {
            return "Table comment.\nSecond paragraph.\n\nAfter an empty line.";
        }
        if (path == P{"t", "v"}) {
            return "Array of tables comment (first element only).";
        }
        if (path == P{"arr"}) {
            return "Groups.";
        }
        if (path == P{"arr", "name"}) {
            return "Name (stack depth " + std::to_string(stack.size()) + ").";
        }
        if (path == P{"t", "deep", "z"}) {
            return "   ";
        }
        return std::nullopt;
    };
    const std::string text = dumpToml(data, doc, {"Header line one.", "", "Header line three."});
    EXPECT_EQ(text, readFile(kText / "tomlio_golden.toml"));
    // and it reads back to the same data (None entries dropped, NaN aside)
    const Value back = parseToml(text, "golden");
    EXPECT_EQ(back.find("s")->stringOr(), data.find("s")->stringOr());
    EXPECT_EQ(back.find("m")->stringOr(), data.find("m")->stringOr());
    EXPECT_EQ(back.find("none"), nullptr);
    EXPECT_TRUE(std::isnan(*back.find("nan")->get<double>()));
}

TEST(TomlWriter, Values) {
    EXPECT_EQ(tomlKey("format_version"), "format_version");
    EXPECT_EQ(tomlKey("a.b"), "\"a.b\"");
    EXPECT_EQ(tomlValue(Table{}), "{}");
    EXPECT_EQ(tomlValue(Table{{"x", Value()}}), "{  }");  // tomlio: every entry is None
    EXPECT_EQ(tomlValue(Table{{"a", 1}, {"b", "c"}}), "{ a = 1, b = \"c\" }");
    EXPECT_EQ(tomlValue(1.0), "1.0");
    EXPECT_EQ(tomlValue(1e16), "1e+16");
    EXPECT_EQ(tomlQuote("caf\xe9"), "\"caf\xef\xbf\xbd\"");
}
